package com.myeshopping.invoiceservice;
import com.fasterxml.jackson.databind.ObjectMapper; import com.myeshopping.invoiceservice.dto.InvoiceRequest; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
@SpringBootTest @AutoConfigureMockMvc class InvoiceServiceApplicationTests { @Autowired MockMvc mockMvc; @Autowired ObjectMapper mapper; @Test void invoiceGenerationAndRetrievalShouldWork() throws Exception { InvoiceRequest request=new InvoiceRequest(); request.setOrderId(2001L); request.setPaymentId(4001L); request.setCustomerId(1001L); request.setAmount(39.0); request.setCurrency("USD"); String body=mockMvc.perform(post("/api/v1/invoices").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(request))).andExpect(status().isOk()).andExpect(jsonPath("$.data.invoiceNumber").isNotEmpty()).andExpect(jsonPath("$.data.amount").value(39.0)).andReturn().getResponse().getContentAsString(); long id=mapper.readTree(body).path("data").path("id").asLong(); mockMvc.perform(post("/api/v1/invoices").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(request))).andExpect(status().isOk()).andExpect(jsonPath("$.data.id").value(id)); mockMvc.perform(get("/api/v1/invoices/order/2001")).andExpect(status().isOk()).andExpect(jsonPath("$.data.orderId").value(2001)); } }
